def alinear_ruta_tienda(apps, schema_editor):
    """
    La ruta "Vestido en tienda" toma el mismo tipo de tiempo (trabajo o
    espera) que cada proceso tiene en las demás rutas (p. ej. lavandería).
    """
    from collections import Counter

    PlantillaOperacion = apps.get_model("core", "PlantillaOperacion")
    for plantilla in PlantillaOperacion.objects.filter(ruta__taller="T"):
        tipos = Counter(
            PlantillaOperacion.objects.filter(operacion_id=plantilla.operacion_id)
            .exclude(ruta__taller="T")
            .values_list("tipo_tiempo", flat=True)
        )
        if tipos:
            tipo = tipos.most_common(1)[0][0]
            if tipo != plantilla.tipo_tiempo:
                plantilla.tipo_tiempo = tipo
                plantilla.save(update_fields=["tipo_tiempo"])


def enlazar_datos_existentes(apps, schema_editor):
    """Liga reservas a sus pasos y fija el inicio de los pasos en curso."""
    PasoVestido = apps.get_model("core", "PasoVestido")
    ReservaOperacion = apps.get_model("core", "ReservaOperacion")
    SesionVestido = apps.get_model("core", "SesionVestido")

    for paso in PasoVestido.objects.exclude(plantilla__isnull=True):
        ReservaOperacion.objects.filter(
            vestido_id=paso.vestido_id, plantilla_id=paso.plantilla_id, paso__isnull=True
        ).update(paso=paso)

    for paso in PasoVestido.objects.filter(estado__in=["EN_CURSO", "COMPLETADO"], iniciado_en__isnull=True):
        primera = SesionVestido.objects.filter(paso=paso).order_by("inicio").first()
        paso.iniciado_en = primera.inicio if primera else (paso.completado_en or paso.vestido.creado_en)
        paso.save(update_fields=["iniciado_en"])


